Here's how to handle each scenario with modern MSTest (3.9+):

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class PlatformSpecificTests
{
    // 1. Windows-only (registry access)
    [TestMethod]
    [OSCondition(OperatingSystems.Windows)]
    public void Registry_ReadsExpectedValue()
    {
        var value = Registry.GetValue(@"HKEY_LOCAL_MACHINE\SOFTWARE\MyApp", "Setting", null);
        Assert.IsNotNull(value);
    }

    // 2. Skip in CI (requires local GPU)
    [TestMethod]
    [CICondition(ConditionMode.Exclude)]
    public void RenderFrame_ProducesValidOutput()
    {
        var result = GpuRenderer.RenderFrame();
        Assert.IsNotNull(result);
    }

    // 3. Flaky external API — retry up to 3 times
    [TestMethod]
    [Retry(3)]
    [Timeout(10000)]
    public async Task WeatherApi_ReturnsForecast(TestContext testContext)
    {
        var forecast = await _client.GetForecastAsync(testContext.CancellationToken);
        Assert.IsNotNull(forecast);
    }

    // 4. Cleanup temp files even on failure — use [TestCleanup]
    private string? _tempFile;

    [TestMethod]
    public void Export_WritesValidFile()
    {
        _tempFile = Path.GetTempFileName();
        Exporter.WriteTo(_tempFile);
        Assert.IsNotEmpty(File.ReadAllText(_tempFile));
    }

    [TestCleanup]
    public void Cleanup()
    {
        if (_tempFile is not null && File.Exists(_tempFile))
            File.Delete(_tempFile);
    }
}
```

**Key points:**

| Scenario | Solution |
|----------|----------|
| Windows-only | `[OSCondition(OperatingSystems.Windows)]` — test is skipped (not failed) on other OSes |
| Skip in CI | `[CICondition(ConditionMode.Exclude)]` — skipped when CI env vars are detected |
| Flaky API | `[Retry(3)]` — retries up to 3 times before reporting failure |
| Cleanup on failure | `[TestCleanup]` — runs after every test regardless of pass/fail |

**Notes:**
- `[OSCondition]` requires MSTest 3.10+
- `[Retry]` requires MSTest 3.9+ — use only for genuine external flakiness, not internal race conditions
- `[TestCleanup]` always runs (even on exception). For `IDisposable` resources, you can also implement `IDisposable`/`IAsyncDisposable` on the test class.
